WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT l.id, l.nome, l.origem, l.criado_em, e.nome AS usuario, count(p.id) AS total, count(p.id) FILTER (WHERE p.status = 'na_fila') AS na_fila, count(p.id) FILTER (WHERE p.status IN ('extraindo', 'curadoria', 'aguardando_anexo')) AS buscando, count(p.id) FILTER (WHERE p.status = 'criando') AS criando, count(p.id) FILTER (WHERE p.status = 'concluido') AS concluidos, count(p.id) FILTER (WHERE p.status IN ('falhou', 'precisa_catalogo')) AS falharam, max(p.atualizado_em) AS atualizado_em FROM lotes l JOIN eu ON (eu.admin OR l.executivo_id = eu.executivo_id) JOIN executivos e ON e.id = l.executivo_id LEFT JOIN pedidos p ON p.lote_id = l.id GROUP BY l.id, l.nome, l.origem, l.criado_em, e.nome ORDER BY l.id DESC LIMIT CAST(:limite AS INTEGER) OFFSET CAST(:offset AS INTEGER)
